head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "uldmgt50303";
scwin.viewDiv = null;
scwin.editDiv = null;
scwin.viewButtonGroup = null;
scwin.editButtonGroup = null;

///////// 2. 초기화 영역 /////////
// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — viewMode

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "editTab", attr: "src", fn: function () { return "/img/filing/body/tab_2_" + String(((String((dma_pageContext.get("viewMode") ?? "")) === "edit") ? "selected" : "unselected")) + ".gif"; } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_viewMode", fn: function(){ return ((dma_pageContext.get("viewMode") ?? "") === 'view'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_editForm = { action: "", method: 'post', target: '' };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.viewDiv = $c.util.getComponent('viewDiv');
        scwin.editDiv = $c.util.getComponent('editDiv');
        scwin.viewButtonGroup = $c.util.getComponent('viewButtonGroup');
        scwin.editButtonGroup = $c.util.getComponent('editButtonGroup');
        scwin.init_attrReals();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'uldmgt50303.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name viewTab_onclick
 * @description viewTab 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.viewTab_onclick = function(e){
    try {
        scwin.view()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt50303.viewTab_onclick' }); }
};

/**
 * @method
 * @name editTab_onclick
 * @description editTab 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.editTab_onclick = function(e){
    try {
        scwin.edit()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt50303.editTab_onclick' }); }
};

/**
 * @method
 * @name img_48_onclick
 * @description img_48 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_48_onclick = async function(e){
    try {
        await scwin.deleteUpdateReq()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50303.img_48_onclick' }); }
};

/**
 * @method
 * @name img_49_onclick
 * @description img_49 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_49_onclick = function(e){
    try {
        scwin.close()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt50303.img_49_onclick' }); }
};

/**
 * @method
 * @name img_51_onclick
 * @description img_51 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_51_onclick = async function(e){
    try {
        await scwin.update()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50303.img_51_onclick' }); }
};

/**
 * @method
 * @name img_52_onclick
 * @description img_52 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_52_onclick = function(e){
    try {
        scwin.close()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt50303.img_52_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Update
 * @description Update 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Update = async function () {
    const sbmOptions = {
        id: "tx_fn_Update",
        method: "post",
        action: "/filing/updateSystemInfo.do",
        ref: "dma_UpdateReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_Delete
 * @description Delete 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Delete = async function () {
    const sbmOptions = {
        id: "tx_fn_Delete",
        method: "post",
        action: "/filing/updateSystemInfo.do",
        ref: "dma_DeleteReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name view
 * @description view 처리
 * @returns {void}
 * @hidden N
 */
scwin.view = function () {
    $c.util.getComponent('viewTab').setSrc("/img/filing/body/tab_1_selected.gif");
    $c.util.getComponent('editTab').setSrc("/img/filing/body/tab_2_unselected.gif");
    scwin.viewDiv.setStyle("display", "block");
    scwin.editDiv.setStyle("display", "none");
    scwin.viewButtonGroup.setStyle("display", "block");
    scwin.editButtonGroup.setStyle("display", "none");
};

/**
 * @method
 * @name edit
 * @description edit 처리
 * @returns {void}
 * @hidden N
 */
scwin.edit = function () {
    $c.util.getComponent('viewTab').setSrc("/img/filing/body/tab_1_unselected.gif");
    $c.util.getComponent('editTab').setSrc("/img/filing/body/tab_2_selected.gif");
    scwin.viewDiv.setStyle("display", "none");
    scwin.editDiv.setStyle("display", "block");
    scwin.viewButtonGroup.setStyle("display", "none");
    scwin.editButtonGroup.setStyle("display", "block");
};

/**
 * @method
 * @name update
 * @description update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function () {
    $c.util.getComponent('dma_UpdateReq').set('method', "updateSystemInfo");
    scwin.form_editForm.action = "/filing/updateSystemInfo.do";
    await scwin.tx_fn_Update();
};

/**
 * @method
 * @name deleteUpdateReq
 * @description delete Update Req 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.deleteUpdateReq = async function () {
    const _confirm = await $c.win.confirm("제도안내를\n삭제하시겠습니까?");
    if (!_confirm) {
        return;
    }
    scwin.form_editForm.action = "/filing/updateSystemInfo.do";
    $c.util.getComponent('dma_UpdateReq').set('method', "deleteSystemInfo");
    await scwin.tx_fn_Delete();
};

/**
 * @method
 * @name close
 * @description close 처리
 * @returns {void}
 * @hidden N
 */
scwin.close = function () {
    $c.win.closePopup();
};
